// @ts-nocheck
import { useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import { Activity, Archive, ArrowRight, Check, ChevronRight, Download, Eye, FileEdit, FileText, ImagePlus, LayoutTemplate, LoaderCircle, PackageOpen, Palette, Play, Plus, RefreshCw, RotateCcw, Save, Settings2, Sparkles, TestTube2, Upload, X } from "lucide-react";
import { api, ApiError, artifactUrl, requestKey } from "./api/client";
import type { EntryMode, Page, Plan, Preflight, Project, ProviderProfile } from "./types";
import "./styles.css";

const entries: { id: EntryMode; label: string; detail: string; icon: typeof FileText }[] = [
  { id: "document_create", label: "文档生成", detail: "Markdown、TXT、DOCX 或 PDF", icon: FileText },
  { id: "page_entry", label: "逐页录入", detail: "逐页保留原文换行", icon: LayoutTemplate },
  { id: "pptx_improve", label: "改进已有 PPTX", detail: "重设计或高保真重建", icon: Upload },
];

const statusText: Record<string, string> = {
  awaiting_content_confirmation: "等待内容确认", awaiting_design_confirmation: "等待设计确认", generating_visuals: "视觉稿生成中",
  awaiting_representative_confirmation: "等待代表页确认", awaiting_visual_confirmation: "等待视觉审批", reconstructing: "可编辑重建中",
  completed: "已完成", cancelled: "已取消", superseded: "已被重新生成替代", failed: "需要处理", partial: "部分完成",
};
const DRAFT_SESSION_ID = "draft_session";

function App() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [selected, setSelected] = useState<Project | null>(null);
  const [entry, setEntry] = useState<EntryMode>("document_create");
  const [showAdmin, setShowAdmin] = useState(false);
  const [showTasks, setShowTasks] = useState(false);
  const [profiles, setProfiles] = useState<ProviderProfile[]>([]);
  const [profileDraft, setProfileDraft] = useState({ display_name: "", endpoint_mode: "relay", base_url: "", secret_reference: "env:FASTPPT_MODEL_API_KEY", capability_settings: '{"agent":{"backend":"codex","model":"gpt-5.2"},"image_generation":{"model":"gpt-image-2"},"image_edit":{"model":"gpt-image-2"}}' });
  const [newName, setNewName] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);
  const [showInput, setShowInput] = useState(false);
  const [inputText, setInputText] = useState("");
  const [inputFile, setInputFile] = useState<File | null>(null);
  const [busy, setBusy] = useState(false);
  const [flowStatus, setFlowStatus] = useState("");
  const [activePlan, setActivePlan] = useState<Plan | null>(null);
  const [pages, setPages] = useState<Page[]>([]);
  const [production, setProduction] = useState<Record<string, any>>({});
  const [jobs, setJobs] = useState<any[]>([]);
  const [agentRuns, setAgentRuns] = useState<any[]>([]);
  const [imageRuns, setImageRuns] = useState<any[]>([]);
  const [revisions, setRevisions] = useState<any[]>([]);
  const [preflight, setPreflight] = useState<Preflight | null>(null);
  const [design, setDesign] = useState({ contentMode: "strict_preserve", improvementMode: "redesign", representativePreflight: false, pageWidth: "13.333", pageHeight: "7.5", pageUnit: "inch", zhFont: "Microsoft YaHei", latinFont: "Arial", language: "", audience: "", purpose: "", pageCountMode: "auto", pageCountExact: "10", pageCountMin: "5", pageCountMax: "12", logicDiagnosis: false, outputMarkdown: true, outputTxt: false, outputDocx: false, userInstruction: "" });
  const [workspaceView, setWorkspaceView] = useState<"project" | "design">("project");
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [designPacks, setDesignPacks] = useState<any[]>([]);
  const [packTab, setPackTab] = useState<"style" | "template">("style");
  const [selectedPack, setSelectedPack] = useState<any | null>(null);
  const [packFiles, setPackFiles] = useState<File[]>([]);
  const [packFile, setPackFile] = useState<File | null>(null);
  const [currentSelection, setCurrentSelection] = useState<any>({ style_pack_id: null, template_pack_id: null, selection_source: "none" });
  const [pendingDesignSelection, setPendingDesignSelection] = useState<any | null>(null);
  const [editInstruction, setEditInstruction] = useState("");
  const [pendingOperation, setPendingOperation] = useState<any | null>(null);
  const [runInspection, setRunInspection] = useState<any | null>(null);
  const [planDrafts, setPlanDrafts] = useState<any[]>([]);
  const [planDirty, setPlanDirty] = useState(false);

  const activeEntry = useMemo(() => entries.find((item) => item.id === entry)!, [entry]);

  async function refreshProjects() {
    try { const result = await api<{ projects: Project[] }>("/projects"); setProjects(result.projects); if (!selected && result.projects[0]) setSelected(result.projects[0]); }
    catch (reason) { setError(reason instanceof Error ? reason.message : "无法加载项目"); }
    finally { setLoading(false); }
  }

  async function refreshFlow(projectId = selected?.project_id) {
    if (!projectId) return;
    try {
      const [pageResult, planResult, jobsResult, agentResult, imageResult, revisionResult] = await Promise.all([
        api<{ pages: Page[] }>(`/projects/${projectId}/pages`), api<{ plans: Plan[] }>(`/projects/${projectId}/plans`), api<{ jobs: any[] }>(`/projects/${projectId}/jobs`),
        api<{ agent_runs: any[] }>(`/projects/${projectId}/agent-runs`), api<{ image_runs: any[] }>(`/projects/${projectId}/image-runs`), api<{ deck_revisions: any[] }>(`/projects/${projectId}/deck-revisions`),
      ]);
      setPages(pageResult.pages || []); setJobs(jobsResult.jobs || []); setAgentRuns(agentResult.agent_runs || []); setImageRuns(imageResult.image_runs || []); setRevisions(revisionResult.deck_revisions || []);
      const latest = planResult.plans?.[0] || null;
      setActivePlan((current) => current && planResult.plans.some((item) => item.plan_id === current.plan_id) ? (planResult.plans.find((item) => item.plan_id === current.plan_id) || current) : latest);
      if (latest?.session_id) {
        setCurrentSessionId(latest.session_id);
        try { setCurrentSelection(await api<any>(`/projects/${projectId}/sessions/${latest.session_id}/design-selection`)); } catch { setCurrentSelection({ style_pack_id: null, template_pack_id: null, selection_source: "none" }); }
      }
      const states = await Promise.all((pageResult.pages || []).map(async (page) => { try { return [page.page_id, await api<any>(`/projects/${projectId}/pages/${page.page_id}/production-state`)] as const; } catch { return [page.page_id, null] as const; } }));
      setProduction(Object.fromEntries(states));
    } catch (reason) { setError(reason instanceof Error ? reason.message : "无法读取生产状态"); }
  }

  useEffect(() => { void refreshProjects(); }, []);
  useEffect(() => { setActivePlan(null); setPages([]); setProduction({}); setCurrentSessionId(null); setCurrentSelection({ style_pack_id: null, template_pack_id: null, selection_source: "none" }); setPendingDesignSelection(null); setWorkspaceView("project"); if (selected) void refreshFlow(selected.project_id); }, [selected?.project_id]);
  useEffect(() => { if (!selected || !activePlan || !["generating_visuals", "reconstructing"].includes(activePlan.status)) return undefined; const timer = window.setInterval(() => void refreshFlow(selected.project_id), 1800); return () => window.clearInterval(timer); }, [selected?.project_id, activePlan?.status]);
  useEffect(() => { if (activePlan?.status === "awaiting_content_confirmation") { setPlanDrafts((activePlan.structured_plan?.pageDrafts || []).map((item: any) => ({ ...item, fact_ids: [...(item.fact_ids || [])] }))); setPlanDirty(false); } }, [activePlan?.plan_id, activePlan?.structured_plan?.contentRevision, activePlan?.status]);
  useEffect(() => { if (packFiles.length && !packFile) setPackFile(packFiles[0]); }, [packFiles, packFile]);

  function showError(reason: unknown, fallback: string) { setError(reason instanceof ApiError ? reason.message : reason instanceof Error ? reason.message : fallback); }
  function openEntry() { if (!selected) return; setError(""); setFlowStatus(""); setInputText(""); setInputFile(null); setShowInput(true); }
  async function createProject() { if (!newName.trim()) return; try { const project = await api<Project>("/projects", { method: "POST", body: JSON.stringify({ name: newName.trim() }) }); setProjects((items) => [project, ...items]); setSelected(project); setNewName(""); } catch (reason) { showError(reason, "创建失败"); } }
  async function fileAsBase64(file: File) { const bytes = new Uint8Array(await file.arrayBuffer()); let binary = ""; for (let index = 0; index < bytes.length; index += 0x8000) binary += String.fromCharCode(...bytes.subarray(index, index + 0x8000)); return btoa(binary); }
  function textAsBase64(value: string) { const bytes = new TextEncoder().encode(value); let binary = ""; for (let index = 0; index < bytes.length; index += 0x8000) binary += String.fromCharCode(...bytes.subarray(index, index + 0x8000)); return btoa(binary); }

  async function submitEntry() {
    if (!selected) return; setBusy(true); setError("");
    try {
      let sourceDocumentIds: string[] = [];
      if (entry !== "page_entry") { if (!inputFile && !inputText.trim()) throw new Error("请选择文件或粘贴文本"); const document = await api<{ document_id: string }>(`/projects/${selected.project_id}/documents`, { method: "POST", headers: { "Idempotency-Key": requestKey("document") }, body: JSON.stringify({ file_name: inputFile?.name || "pasted.txt", content_base64: inputFile ? await fileAsBase64(inputFile) : textAsBase64(inputText) }) }); sourceDocumentIds = [document.document_id]; }
      const pageCount = design.pageCountMode === "exact" ? { mode: "exact", exact: Number(design.pageCountExact) } : design.pageCountMode === "range" ? { mode: "range", min: Number(design.pageCountMin), max: Number(design.pageCountMax) } : { mode: "auto" };
      const outputFormats = [design.outputMarkdown && "markdown", design.outputTxt && "txt", design.outputDocx && "docx"].filter(Boolean);
      const session = await api<{ session_id: string }>(`/projects/${selected.project_id}/sessions`, { method: "POST", headers: { "Idempotency-Key": requestKey("session") }, body: JSON.stringify({ workflow_mode: entry, source_document_ids: sourceDocumentIds, options: { content_mode: design.contentMode, improvement_mode: design.improvementMode, representative_preflight: design.representativePreflight, language: design.language, audience: design.audience, purpose: design.purpose, page_count: pageCount, logic_diagnosis_enabled: design.logicDiagnosis, output_formats: outputFormats, user_instruction: design.userInstruction } }) });
      setCurrentSessionId(session.session_id);
      if (pendingDesignSelection) {
        for (const kind of ["style", "template"] as const) {
          const packId = pendingDesignSelection[`${kind}_pack_id`];
          if (packId) {
            await api<any>(`/projects/${selected.project_id}/sessions/${session.session_id}/design-selection`, { method: "POST", headers: { "Idempotency-Key": requestKey(`design-use-${kind}`) }, body: JSON.stringify({ pack_id: packId, pack_kind: kind }) });
          }
        }
        setPendingDesignSelection(null);
      }
      let pageDrafts: any[] | undefined;
      if (entry === "page_entry") { const chunks = inputText.split(/\r?\n\s*---+\s*\r?\n?/).map((chunk) => chunk.trim()).filter(Boolean); if (!chunks.length) throw new Error("请先输入至少一页内容"); pageDrafts = chunks.map((chunk, index) => { const [first, ...rest] = chunk.split(/\r?\n/); return { title: first.trim() || `第 ${index + 1} 页`, body: rest.join("\n").trim() || first.trim(), page_type: index === 0 ? "cover" : "content" }; }); }
      const plan = await api<Plan>(`/projects/${selected.project_id}/plans`, { method: "POST", headers: { "Idempotency-Key": requestKey("plan") }, body: JSON.stringify({ session_id: session.session_id, page_drafts: pageDrafts }) });
      setActivePlan(plan); setFlowStatus("内容计划已创建"); setShowInput(false); await refreshFlow(selected.project_id);
    } catch (reason) { showError(reason, "入口提交失败"); } finally { setBusy(false); }
  }

  async function persistPlanContent() { if (!selected || !activePlan) return activePlan; const result = await api<Plan>(`/projects/${selected.project_id}/plans/${activePlan.plan_id}/content`, { method: "POST", headers: { "Idempotency-Key": requestKey("plan-content") }, body: JSON.stringify({ page_drafts: planDrafts }) }); setActivePlan(result); setPlanDirty(false); return result; }
  async function savePlanContent() { setBusy(true); setError(""); try { await persistPlanContent(); setFlowStatus("内容计划已保存"); } catch (reason) { showError(reason, "内容计划保存失败"); } finally { setBusy(false); } }
  async function confirmPlan() { if (!selected || !activePlan) return; setBusy(true); setError(""); try { const plan = planDirty ? await persistPlanContent() : activePlan; const result = await api<Plan>(`/projects/${selected.project_id}/plans/${plan.plan_id}/confirm`, { method: "POST", headers: { "Idempotency-Key": requestKey("confirm-content") }, body: "{}" }); setActivePlan(result); setFlowStatus("内容已锁定，请确认设计参数"); } catch (reason) { showError(reason, "内容确认失败"); } finally { setBusy(false); } }
  async function confirmDesign() { if (!selected || !activePlan) return; setBusy(true); setError(""); try { const result = await api<Plan>(`/projects/${selected.project_id}/plans/${activePlan.plan_id}/design/confirm`, { method: "POST", headers: { "Idempotency-Key": requestKey("confirm-design") }, body: JSON.stringify({ representative_preflight: design.representativePreflight, page_size: { width: Number(design.pageWidth), height: Number(design.pageHeight), unit: design.pageUnit }, font_policy: { zh_family: design.zhFont, latin_family: design.latinFont } }) }); setActivePlan(result); setFlowStatus(result.status === "generating_visuals" ? "视觉稿已提交，等待任务完成" : "视觉稿已生成，请逐页审批"); await refreshFlow(selected.project_id); } catch (reason) { showError(reason, "设计确认失败"); } finally { setBusy(false); } }

  async function decideVisual(page: Page, decision: "approve" | "reject") { if (!selected || !page.visual_preview_artifact_id) return; setBusy(true); setError(""); try { const artifact = await api<any>(`/projects/${selected.project_id}/artifacts/${page.visual_preview_artifact_id}/metadata`); await api(`/projects/${selected.project_id}/pages/${page.page_id}/visual/${decision}`, { method: "POST", headers: { "Idempotency-Key": requestKey(`visual-${decision}`) }, body: JSON.stringify({ contract_revision: 1, visual_artifact_id: page.visual_preview_artifact_id, visual_sha256: artifact.sha256, comment: decision === "approve" ? "Web approval" : "Web rejection" }) }); setFlowStatus(decision === "approve" ? "视觉稿已批准" : "视觉稿已拒绝，请处理该页"); await refreshFlow(selected.project_id); } catch (reason) { showError(reason, "视觉审批失败"); } finally { setBusy(false); } }
  async function confirmSamples() { if (!selected || !activePlan) return; setBusy(true); setError(""); try { const result = await api<Plan>(`/projects/${selected.project_id}/plans/${activePlan.plan_id}/samples/confirm`, { method: "POST", headers: { "Idempotency-Key": requestKey("confirm-representatives") }, body: "{}" }); setActivePlan(result); setFlowStatus("代表页已确认，正在生成其余页面"); await refreshFlow(selected.project_id); } catch (reason) { showError(reason, "代表页确认失败"); } finally { setBusy(false); } }
  async function restartPlan() { if (!selected || !activePlan) return; setBusy(true); setError(""); try { const result = await api<Plan>(`/projects/${selected.project_id}/plans/${activePlan.plan_id}/restart`, { method: "POST", headers: { "Idempotency-Key": requestKey("restart-plan") }, body: "{}" }); setActivePlan(result); setFlowStatus("已创建全新的统一计划，请重新确认内容"); await refreshFlow(selected.project_id); } catch (reason) { showError(reason, "从头重新生成失败"); } finally { setBusy(false); } }
  async function openPreflight(page: Page) { if (!selected) return; setBusy(true); setError(""); try { setPreflight(await api<Preflight>(`/projects/${selected.project_id}/pages/${page.page_id}/reconstruction/preflight`)); } catch (reason) { showError(reason, "无法读取重建披露"); } finally { setBusy(false); } }
  async function acceptPreflight() { if (!selected || !preflight) return; setBusy(true); setError(""); try { await api(`/projects/${selected.project_id}/pages/${preflight.page_id}/reconstruct`, { method: "POST", headers: { "Idempotency-Key": requestKey(`reconstruct-${preflight.page_id}`) }, body: JSON.stringify({ disclosure_sha256: preflight.disclosure_sha256, accept_wait_time: true, accept_supplier_fee_risk: true, accept_visual_difference: true, accept_editable_boundary: true, accepted_unsupported_object_ids: preflight.unsupported_items.map((item) => item.object_id) }) }); setPreflight(null); setFlowStatus("重建任务已提交"); await refreshFlow(selected.project_id); } catch (reason) { showError(reason, "重建提交失败"); } finally { setBusy(false); } }

  async function openAdmin() { setShowAdmin(true); setError(""); try { setProfiles((await api<{ profiles: ProviderProfile[] }>("/admin/provider-profiles")).profiles || []); } catch (reason) { showError(reason, "无法读取配置，请确认管理员会话"); } }
  async function createProfile() { setBusy(true); setError(""); try { const profile = await api<ProviderProfile>("/admin/provider-profiles", { method: "POST", headers: { "Idempotency-Key": requestKey("provider-profile") }, body: JSON.stringify({ display_name: profileDraft.display_name, endpoint_mode: profileDraft.endpoint_mode, base_url: profileDraft.endpoint_mode === "relay" ? profileDraft.base_url : undefined, secret_reference: profileDraft.secret_reference, capability_settings: JSON.parse(profileDraft.capability_settings) }) }); setProfiles((items) => [...items, profile]); setProfileDraft((draft) => ({ ...draft, display_name: "" })); } catch (reason) { showError(reason, "配置档案保存失败"); } finally { setBusy(false); } }
  async function profileAction(profileId: string, action: "test" | "archive" | "default") { setBusy(true); setError(""); try { const path = action === "test" ? `/admin/provider-profiles/${profileId}/test` : action === "default" ? `/admin/provider-profiles/${profileId}/default` : `/admin/provider-profiles/${profileId}`; const result = await api<any>(path, { method: action === "archive" ? "DELETE" : "POST", headers: { "Idempotency-Key": requestKey(`profile-${action}`) }, body: JSON.stringify({ capability: "agent" }) }); if (action === "test") setProfiles((items) => items.map((item) => item.profile_id === profileId ? result.profile : item)); else if (action === "archive") setProfiles((items) => items.filter((item) => item.profile_id !== profileId)); else setFlowStatus("默认 Agent 档案已更新"); } catch (reason) { showError(reason, "配置操作失败"); } finally { setBusy(false); } }

  async function loadDesignPacks(kind = packTab) { if (!selected) return; try { const result = await api<{ design_packs: any[] }>(`/projects/${selected.project_id}/design-packs?kind=${kind}`); setDesignPacks(result.design_packs || []); } catch (reason) { showError(reason, "无法读取设计包"); } }
  async function openDesignLibrary() { if (!selected) return; setWorkspaceView("design"); setSelectedPack(null); await loadDesignPacks(); if (currentSessionId && currentSessionId !== DRAFT_SESSION_ID) { try { setCurrentSelection(await api<any>(`/projects/${selected.project_id}/sessions/${currentSessionId}/design-selection`)); } catch { /* The library remains readable without an active session. */ } } else { setCurrentSessionId(DRAFT_SESSION_ID); if (pendingDesignSelection) setCurrentSelection(pendingDesignSelection); } }
  async function switchPackTab(kind: "style" | "template") { setPackTab(kind); setSelectedPack(null); if (selected) { try { const result = await api<{ design_packs: any[] }>(`/projects/${selected.project_id}/design-packs?kind=${kind}`); setDesignPacks(result.design_packs || []); } catch (reason) { showError(reason, "无法读取设计包"); } } }
  async function importPack() {
    const selectedFiles = packFiles.length ? packFiles : packFile ? [packFile] : [];
    if (!selected || !selectedFiles.length) return;
    setBusy(true); setError("");
    try {
      const isZip = selectedFiles.length === 1 && /\.zip$/i.test(selectedFiles[0].name);
      const relativePaths = selectedFiles.map((file) => file.webkitRelativePath || file.name);
      const firstSegment = relativePaths[0].split("/")[0];
      const directoryPrefix = firstSegment && relativePaths.every((path) => path.startsWith(`${firstSegment}/`)) ? `${firstSegment}/` : "";
      const body = isZip
        ? { content_base64: await fileAsBase64(selectedFiles[0]) }
        : { directory_files: await Promise.all(selectedFiles.map(async (file, index) => ({ path: relativePaths[index].replace(directoryPrefix, ""), content_base64: await fileAsBase64(file) }))) };
      await api(`/projects/${selected.project_id}/design-packs/import`, { method: "POST", headers: { "Idempotency-Key": requestKey("design-import") }, body: JSON.stringify(body) });
      setPackFiles([]); setPackFile(null); await loadDesignPacks(); setFlowStatus("设计包已导入");
    } catch (reason) { showError(reason, "设计包导入失败"); } finally { setBusy(false); }
  }
  function applyPackToSelection(base: any, pack: any, kind: "style" | "template", packId: string | null) {
    const next = { ...(base || {}), selection_source: base?.selection_source || "none" };
    next[`${kind}_pack_id`] = packId;
    next[`${kind}_display_name`] = packId ? pack?.display_name || packId : null;
    next[`${kind}_version`] = packId ? pack?.current_version || pack?.version || null : null;
    next[`${kind}_content_hash`] = packId ? pack?.content_hash || null : null;
    next[`${kind}_scope`] = packId ? pack?.scope || null : null;
    next.selection_source = next.style_pack_id || next.template_pack_id ? (next.style_scope === "private" || next.template_scope === "private" ? "private" : "system") : "none";
    return next;
  }
  async function usePack(pack: any) {
    if (!selected) return;
    setBusy(true); setError("");
    try {
      if (currentSessionId && currentSessionId !== DRAFT_SESSION_ID) {
        const selection = await api<any>(`/projects/${selected.project_id}/sessions/${currentSessionId}/design-selection`, { method: "POST", headers: { "Idempotency-Key": requestKey(`design-use-${pack.pack_kind}`) }, body: JSON.stringify({ pack_id: pack.pack_id, pack_kind: pack.pack_kind }) });
        setCurrentSelection(selection);
      } else {
        const selection = applyPackToSelection(pendingDesignSelection || currentSelection, pack, pack.pack_kind, pack.pack_id);
        setPendingDesignSelection(selection); setCurrentSelection(selection);
      }
      setFlowStatus(`${pack.display_name} 已加入当前生成选择`);
    } catch (reason) { showError(reason, "设计包选择失败"); } finally { setBusy(false); }
  }
  async function clearPack(kind: "style" | "template") {
    if (!selected) return;
    setBusy(true); setError("");
    try {
      if (currentSessionId && currentSessionId !== DRAFT_SESSION_ID) {
        setCurrentSelection(await api<any>(`/projects/${selected.project_id}/sessions/${currentSessionId}/design-selection`, { method: "POST", headers: { "Idempotency-Key": requestKey(`design-clear-${kind}`) }, body: JSON.stringify({ pack_id: null, pack_kind: kind }) }));
      } else {
        const selection = applyPackToSelection(pendingDesignSelection || currentSelection, null, kind, null);
        setPendingDesignSelection(selection); setCurrentSelection(selection);
      }
      setFlowStatus(`${kind === "style" ? "风格" : "模板"}选择已取消`);
    } catch (reason) { showError(reason, "取消选择失败"); } finally { setBusy(false); }
  }
  async function exportContent(format: "markdown" | "txt" | "docx") { if (!selected || !activePlan) return; try { const result = await api<any>(`/projects/${selected.project_id}/plans/${activePlan.plan_id}/content-export`, { method: "POST", headers: { "Idempotency-Key": requestKey(`content-${format}`) }, body: JSON.stringify({ format }) }); window.location.assign(artifactUrl(selected.project_id, result.artifact_id)); } catch (reason) { showError(reason, "内容计划导出失败"); } }
  async function createEdit() { if (!selected || !editInstruction.trim() || !pages.length) return; setBusy(true); setError(""); try { const operation = await api<any>(`/projects/${selected.project_id}/operations`, { method: "POST", body: JSON.stringify({ instruction: editInstruction.trim(), target_scope: "global", page_ids: [], workflow_mode: activePlan?.structured_plan?.workflowMode || "page_entry" }) }); if (operation.confirmation_required) setPendingOperation(operation); else { setEditInstruction(""); await refreshFlow(); } } catch (reason) { showError(reason, "编辑规划失败"); } finally { setBusy(false); } }
  async function confirmEdit() { if (!selected || !pendingOperation) return; setBusy(true); try { await api(`/projects/${selected.project_id}/operations/${pendingOperation.operation_id}/confirm`, { method: "POST", headers: { "Idempotency-Key": requestKey("confirm-edit") }, body: "{}" }); setPendingOperation(null); setEditInstruction(""); await refreshFlow(); } catch (reason) { showError(reason, "编辑确认失败"); } finally { setBusy(false); } }
  async function inspectRun(run: any) { if (!selected) return; try { const [prompt, context] = await Promise.all([api<any>(`/projects/${selected.project_id}/agent-runs/${run.agent_run_id}/prompt`), api<any>(`/projects/${selected.project_id}/agent-runs/${run.agent_run_id}/context`)]); setRunInspection({ ...prompt, context }); } catch (reason) { showError(reason, "Prompt 检查失败"); } }
  async function dryReplay(run: any) { if (!selected) return; try { setRunInspection(await api<any>(`/projects/${selected.project_id}/agent-runs/${run.agent_run_id}/replay`, { method: "POST", body: JSON.stringify({ execute: false }) })); } catch (reason) { showError(reason, "Prompt 重放检查失败"); } }
  function updatePlanDraft(index: number, values: Record<string, any>) { setPlanDrafts((items) => items.map((item, itemIndex) => itemIndex === index ? { ...item, ...values } : item)); setPlanDirty(true); }
  function addPlanDraft() { setPlanDrafts((items) => [...items, { page_draft_id: `client_${Date.now()}`, title: "新页面", body: "", central_claim: "", fact_ids: [], visual_suggestion: "", page_type: "content" }]); setPlanDirty(true); }
  function removePlanDraft(index: number) { setPlanDrafts((items) => items.length > 1 ? items.filter((_item, itemIndex) => itemIndex !== index) : items); setPlanDirty(true); }
  function downloadAudit() { if (selected) window.location.assign(`/api/v1/projects/${selected.project_id}/audit-export`); }
  function selectionName(kind: "style" | "template") { return currentSelection[`${kind}_display_name`] || currentSelection[`${kind}_pack_id`] || "未选择"; }

  const approvedCount = pages.filter((page) => production[page.page_id]?.visual_approval_id).length;
  const readyCount = pages.filter((page) => page.version_status === "ready" && page.svg_artifact_id).length;
  return <div className="app-shell"><header className="topbar"><div className="brand"><span className="brand-mark">F</span><span>FastPPT</span><small>工作台</small></div><div className="topbar-actions"><span className="save-state"><span className="status-dot" />状态已保存</span><button className="icon-button" title="管理员设置" aria-label="管理员设置" onClick={() => void openAdmin()}><Settings2 size={18} /></button></div></header>
    <main className="workspace"><aside className="sidebar" aria-label="演示项目导航"><div className="sidebar-heading"><span>演示项目</span><button className="icon-button" title="新建演示项目" aria-label="新建演示项目" onClick={() => document.getElementById("project-name")?.focus()}><Plus size={18} /></button></div><div className="project-create"><input id="project-name" value={newName} onChange={(event) => setNewName(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") void createProject(); }} placeholder="新建演示项目" /><button className="create-button" onClick={() => void createProject()} aria-label="创建项目"><ArrowRight size={16} /></button></div><div className="project-list">{loading ? <div className="empty-state">正在读取项目…</div> : projects.length ? projects.map((project) => <button key={project.project_id} className={`project-item ${selected?.project_id === project.project_id ? "active" : ""}`} onClick={() => { setSelected(project); setWorkspaceView("project"); }}><span className="project-avatar">{project.name.slice(0, 1)}</span><span><strong>{project.name}</strong><small>{project.status === "draft" ? "草稿" : project.status}</small></span></button>) : <div className="empty-state">还没有演示项目</div>}</div><button className={`sidebar-tool ${workspaceView === "design" ? "active" : ""}`} disabled={!selected} onClick={() => void openDesignLibrary()}><Palette size={17} /><span>风格和模板</span></button>{workspaceView === "design" && <label className="sidebar-tool directory-import"><Upload size={17} /><span>导入目录</span><input type="file" multiple accept=".json,.png,.jpg,.jpeg,.webp,.svg" {...({ webkitdirectory: "", directory: "" } as any)} onChange={(event) => setPackFiles(Array.from(event.target.files || []))} /></label>}</aside>
      <section className="content-area">{workspaceView === "design" ? <><div className="content-header"><div><p className="eyebrow">设计资源</p><h1>风格和模板</h1><p className="selection-state">当前风格：{selectionName("style")} · 当前模板：{selectionName("template")}</p></div><button className="secondary-button" onClick={() => setWorkspaceView("project")}><ArrowRight size={16} />返回项目</button></div><div className="pack-toolbar"><div className="pack-tabs" role="tablist"><button className={packTab === "style" ? "active" : ""} onClick={() => void switchPackTab("style")}><Palette size={16} />风格</button><button className={packTab === "template" ? "active" : ""} onClick={() => void switchPackTab("template")}><LayoutTemplate size={16} />模板</button></div><label className="secondary-button pack-import"><Upload size={15} />{packFile?.name || "导入 Bundle"}<input type="file" accept=".zip" onChange={(event) => setPackFile(event.target.files?.[0] || null)} /></label>{packFile && <button className="primary-button" disabled={busy} onClick={() => void importPack()}><PackageOpen size={15} />导入</button>}<button className="text-button" disabled={!currentSessionId} onClick={() => void clearPack(packTab)}><X size={15} />取消当前选择</button></div><div className="pack-workspace"><div className="pack-list">{designPacks.length ? designPacks.map((pack) => <button key={pack.pack_id} className={`pack-row ${selectedPack?.pack_id === pack.pack_id ? "active" : ""}`} onClick={() => setSelectedPack(pack)}>{pack.preview_count > 0 && selected ? <img className="pack-thumb" src={`/api/v1/projects/${selected.project_id}/design-packs/${pack.pack_id}/previews/0`} alt="" /> : <span className="pack-kind-icon">{pack.pack_kind === "style" ? <Palette size={18} /> : <LayoutTemplate size={18} />}</span>}<span><strong>{pack.display_name}</strong><small>{pack.current_version} · {pack.scope === "private" ? "私人" : "系统"}</small></span><ChevronRight size={16} /></button>) : <div className="empty-state">暂无可见资源</div>}</div><section className="pack-detail">{selectedPack ? <>{selectedPack.preview_count > 0 && selected && <img className="pack-preview" src={`/api/v1/projects/${selected.project_id}/design-packs/${selectedPack.pack_id}/previews/0`} alt={`${selectedPack.display_name} 预览`} />}<div className="panel-heading"><div><p className="eyebrow">{selectedPack.pack_kind === "style" ? "风格" : "模板"}</p><h2>{selectedPack.display_name}</h2></div><span className="status-pill ready">{selectedPack.status}</span></div><p>{selectedPack.description || ""}</p><dl><div><dt>版本</dt><dd>{selectedPack.current_version}</dd></div><div><dt>适用页面</dt><dd>{selectedPack.manifest?.supported_page_types?.join("、") || "未声明"}</dd></div><div><dt>来源</dt><dd>{selectedPack.source}</dd></div><div><dt>许可证</dt><dd>{selectedPack.manifest?.license || "未声明"}</dd></div><div><dt>内容哈希</dt><dd>{selectedPack.content_hash}</dd></div></dl><button className="primary-button" disabled={!currentSessionId || busy} onClick={() => void usePack(selectedPack)}><Check size={16} />使用</button></> : <div className="empty-state">选择一项查看详情</div>}</section></div></> : <><div className="content-header"><div><p className="eyebrow">演示项目</p><h1>{selected?.name || "创建第一份演示"}</h1><p className="selection-state">风格：{selectionName("style")} · 模板：{selectionName("template")}{activePlan?.structured_plan?.consistencyStatus?.startsWith("mixed_") ? ` · ${activePlan.structured_plan.consistencyStatus}` : ""}</p></div>{selected && <button className="secondary-button" onClick={() => setShowTasks(true)}><Activity size={16} />任务与版本</button>}</div>
        <div className="entry-grid">{entries.map(({ id, label, detail, icon: Icon }) => <button key={id} className={`entry-option ${entry === id ? "selected" : ""}`} onClick={() => setEntry(id)}><span className="entry-icon"><Icon size={20} /></span><span className="entry-copy"><strong>{label}</strong><small>{detail}</small></span>{entry === id && <Check className="entry-check" size={17} />}</button>)}</div>
        <div className="flow-band"><div className={`flow-step ${activePlan?.status === "awaiting_content_confirmation" ? "active" : ""}`}><span>01</span><strong>内容确认</strong></div><ChevronRight size={16} /><div className={`flow-step ${activePlan?.status === "awaiting_design_confirmation" ? "active" : ""}`}><span>02</span><strong>设计确认</strong></div><ChevronRight size={16} /><div className={`flow-step ${["awaiting_representative_confirmation", "awaiting_visual_confirmation", "generating_visuals"].includes(activePlan?.status) ? "active" : ""}`}><span>03</span><strong>视觉审批</strong></div><ChevronRight size={16} /><div className={`flow-step ${activePlan?.status === "completed" ? "active" : ""}`}><span>04</span><strong>可编辑重建</strong></div></div>
        <section className="start-panel"><div className="start-panel-icon"><Sparkles size={22} /></div><div><h2>{activePlan ? statusText[activePlan.status] || activePlan.status : activeEntry.label}</h2><p>{activePlan ? `计划 ${activePlan.plan_id} · ${activePlan.structured_plan?.pageDrafts?.length || pages.length || 0} 页` : activeEntry.detail}</p><div className="start-actions"><button className="primary-button" disabled={!selected || busy} onClick={openEntry}><Sparkles size={17} />开始{activeEntry.label}</button>{activePlan?.status === "awaiting_content_confirmation" && <button className="secondary-button" disabled={busy} onClick={() => void confirmPlan()}><Check size={16} />确认内容计划</button>}{activePlan?.status === "awaiting_design_confirmation" && <button className="secondary-button" disabled={busy} onClick={() => void confirmDesign()}><Check size={16} />确认设计并生成视觉稿</button>}{activePlan?.status === "awaiting_representative_confirmation" && <button className="secondary-button" disabled={busy} onClick={() => void confirmSamples()}><Check size={16} />确认代表页</button>}{activePlan?.structured_plan?.consistencyStatus?.startsWith("mixed_") && <button className="secondary-button" disabled={busy} onClick={() => void restartPlan()}><RefreshCw size={16} />从头重新生成</button>}</div>{flowStatus && <div className="flow-status" role="status">{flowStatus}</div>}</div></section>
        {activePlan?.status === "awaiting_design_confirmation" && <section className="settings-strip"><div><strong>生产参数</strong><small>这些参数会写入页面合同</small></div><label>内容模式<select value={design.contentMode} onChange={(event) => setDesign({ ...design, contentMode: event.target.value })}><option value="strict_preserve">严格保留</option><option value="assisted">辅助整理</option></select></label><label>改进模式<select value={design.improvementMode} onChange={(event) => setDesign({ ...design, improvementMode: event.target.value })}><option value="redesign">默认重设计</option><option value="high_fidelity">高保真</option></select></label><label className="check-label"><input type="checkbox" checked={design.representativePreflight} onChange={(event) => setDesign({ ...design, representativePreflight: event.target.checked })} />主动预检代表页</label><label>页面尺寸<input value={`${design.pageWidth} x ${design.pageHeight}`} onChange={(event) => { const [width, height] = event.target.value.split("x").map((item) => item.trim()); setDesign({ ...design, pageWidth: width || design.pageWidth, pageHeight: height || design.pageHeight }); }} /></label></section>}
        {activePlan?.status === "awaiting_content_confirmation" && <section className="content-plan">
          <div className="section-heading"><div><p className="eyebrow">内容计划</p><h2>{planDrafts.length} 页 · {activePlan.structured_plan?.language}</h2></div><div className="content-export-actions"><button className="text-button" onClick={() => void exportContent("markdown")}>MD</button><button className="text-button" onClick={() => void exportContent("txt")}>TXT</button><button className="text-button" onClick={() => void exportContent("docx")}>DOCX</button><button className="secondary-button" disabled={planDrafts.length >= 100 || busy} onClick={addPlanDraft}><Plus size={14} />添加一页</button><button className="secondary-button" disabled={!planDirty || busy} onClick={() => void savePlanContent()}><Save size={14} />保存修改</button></div></div>
          <div className="plan-meta"><span>受众<strong>{activePlan.structured_plan?.audience}</strong></span><span>目的<strong>{activePlan.structured_plan?.purpose}</strong></span><span>页数依据<strong>{activePlan.structured_plan?.pageCount?.reason}</strong></span></div>
          <div className="storyline"><strong>页间叙事</strong><span>{activePlan.structured_plan?.storyline?.join(" → ")}</span></div>
          {activePlan.structured_plan?.logicDiagnosisSummary && <div className="logic-summary"><strong>{activePlan.structured_plan.logicDiagnosisSummary.logicType}</strong><span>{activePlan.structured_plan.logicDiagnosisSummary.centralClaim}</span></div>}
          <div className="draft-list">{planDrafts.map((draft: any, index: number) => <article key={draft.page_draft_id || index}><span>{String(index + 1).padStart(2, "0")}</span><div className="draft-fields"><label>标题<input value={draft.title || ""} onChange={(event) => updatePlanDraft(index, { title: event.target.value })} /></label><label>核心观点<textarea rows={2} value={draft.central_claim || draft.core_point || ""} onChange={(event) => updatePlanDraft(index, { central_claim: event.target.value, core_point: event.target.value })} /></label><label>正文<textarea rows={5} value={draft.body || ""} onChange={(event) => updatePlanDraft(index, { body: event.target.value })} /></label><div className="draft-secondary"><label>事实锚点<input value={(draft.fact_ids || []).join(", ")} onChange={(event) => updatePlanDraft(index, { fact_ids: event.target.value.split(",").map((item) => item.trim()).filter(Boolean) })} /></label><label>视觉建议<input value={draft.visual_suggestion || ""} onChange={(event) => updatePlanDraft(index, { visual_suggestion: event.target.value })} /></label></div><button className="text-button draft-remove" disabled={planDrafts.length <= 1 || busy} onClick={() => removePlanDraft(index)}><X size={14} />删除此页</button></div></article>)}</div>
        </section>}
        {pages.length > 0 && <section className="edit-strip"><FileEdit size={18} /><input value={editInstruction} onChange={(event) => setEditInstruction(event.target.value)} placeholder="自然语言编辑" /><button className="secondary-button" disabled={busy || !editInstruction.trim()} onClick={() => void createEdit()}><Play size={15} />规划编辑</button></section>}
        {pages.length > 0 && <section className="gallery-section"><div className="section-heading"><div><p className="eyebrow">视觉画廊</p><h2>{approvedCount}/{pages.length} 页已审批 · {readyCount}/{pages.length} 页可编辑</h2></div><button className="text-button" onClick={() => selected && void refreshFlow(selected.project_id)}><RotateCcw size={15} />刷新</button></div><div className="visual-grid">{pages.map((page) => { const state = production[page.page_id] || {}; const approved = Boolean(state.visual_approval_id); const ready = page.version_status === "ready" && Boolean(page.svg_artifact_id); return <article className="visual-card" key={page.page_id}><div className="visual-frame">{page.visual_preview_artifact_id && selected && <img src={artifactUrl(selected.project_id, page.visual_preview_artifact_id)} alt={`第 ${page.order_index + 1} 页视觉稿`} />}</div><div className="visual-meta"><div><strong>第 {page.order_index + 1} 页 · {page.page_type}</strong><small>{ready ? "可编辑" : approved ? "视觉已批准" : page.version_status}</small></div>{approved ? <Check size={17} className="approved-icon" /> : <span className="status-dot" />}</div><div className="visual-actions">{!approved && page.visual_preview_artifact_id && <><button className="secondary-button" disabled={busy} onClick={() => void decideVisual(page, "approve")}><Check size={14} />批准</button><button className="text-button" disabled={busy} onClick={() => void decideVisual(page, "reject")}><X size={14} />拒绝</button></>}{approved && !ready && <button className="secondary-button" disabled={busy} onClick={() => void openPreflight(page)}><ArrowRight size={14} />重建前检查</button>}{ready && <span className="ready-label">Ready</span>}</div></article>; })}</div></section>}</>}
        {error && <div className="error-banner" role="alert"><X size={16} />{error}<button onClick={() => setError("")} aria-label="关闭错误"><X size={15} /></button></div>}
      </section></main>
    {showAdmin && <div className="modal-backdrop" role="presentation" onClick={() => !busy && setShowAdmin(false)}><section className="admin-panel" role="dialog" aria-modal="true" onClick={(event) => event.stopPropagation()}><div className="panel-heading"><div><p className="eyebrow">管理员</p><h2>连接配置档案</h2></div><button className="icon-button" title="关闭" aria-label="关闭" onClick={() => setShowAdmin(false)}><X size={18} /></button></div><p className="muted">浏览器只提交 Secret 引用，服务端负责解析和审计。</p><div className="profile-list">{profiles.length ? profiles.map((profile) => <div className="profile-row" key={profile.profile_id}><div><strong>{profile.display_name}</strong><small>{profile.endpoint_mode === "relay" ? "中转站" : "官方站"} · Agent {profile.connection_status_by_capability?.agent || "untested"}</small></div><div className="profile-actions"><span className={`status-pill ${profile.enabled ? "ready" : "disabled"}`}>{profile.enabled ? "启用" : "已归档"}</span>{profile.enabled && <><button className="icon-button" title="测试 Agent 连接" aria-label="测试 Agent 连接" onClick={() => void profileAction(profile.profile_id, "test")}><TestTube2 size={15} /></button><button className="icon-button" title="设为默认 Agent" aria-label="设为默认 Agent" onClick={() => void profileAction(profile.profile_id, "default")}><Check size={15} /></button><button className="icon-button" title="归档档案" aria-label="归档档案" onClick={() => void profileAction(profile.profile_id, "archive")}><Archive size={15} /></button></>}</div></div>) : <div className="empty-state">暂无配置档案</div>}</div><div className="profile-form"><input placeholder="档案名称" value={profileDraft.display_name} onChange={(event) => setProfileDraft({ ...profileDraft, display_name: event.target.value })} /><select value={profileDraft.endpoint_mode} onChange={(event) => setProfileDraft({ ...profileDraft, endpoint_mode: event.target.value })}><option value="relay">中转站</option><option value="official">官方站</option></select>{profileDraft.endpoint_mode === "relay" && <input placeholder="HTTPS Base URL" value={profileDraft.base_url} onChange={(event) => setProfileDraft({ ...profileDraft, base_url: event.target.value })} />}<input placeholder="Secret 引用，如 env:FASTPPT_MODEL_API_KEY" value={profileDraft.secret_reference} onChange={(event) => setProfileDraft({ ...profileDraft, secret_reference: event.target.value })} /><textarea value={profileDraft.capability_settings} onChange={(event) => setProfileDraft({ ...profileDraft, capability_settings: event.target.value })} rows={5} /><button className="primary-button" disabled={busy || !profileDraft.display_name.trim()} onClick={() => void createProfile()}><Plus size={15} />保存档案</button></div><div className="diagnostic-line"><ImagePlus size={16} />Agent、文生图和图像编辑能力分别测试。</div></section></div>}
    {showTasks && <div className="modal-backdrop" role="presentation" onClick={() => setShowTasks(false)}><section className="admin-panel" role="dialog" aria-modal="true" onClick={(event) => event.stopPropagation()}><div className="panel-heading"><div><p className="eyebrow">运行记录</p><h2>任务与版本</h2></div><button className="icon-button" title="关闭" aria-label="关闭" onClick={() => setShowTasks(false)}><X size={18} /></button></div><div className="task-summary"><span><strong>{jobs.filter((job) => job.status === "queued" || job.status === "running").length}</strong>进行中</span><span><strong>{agentRuns.length}</strong> AgentRun</span><span><strong>{imageRuns.length}</strong> ImageRun</span><span><strong>{revisions.length}</strong> DeckRevision</span></div><button className="secondary-button" onClick={downloadAudit}><Download size={15} />导出脱敏审计包</button><div className="task-list">{jobs.slice(-6).reverse().map((job) => <div className="task-row" key={job.job_id}><LoaderCircle size={15} className={job.status === "running" ? "spin" : ""} /><span><strong>{job.kind}</strong><small>{job.status} · {job.job_id}</small></span></div>)}</div><div className="run-list">{agentRuns.slice(-8).reverse().map((run) => <div className="run-row" key={run.agent_run_id}><span><strong>{run.role}</strong><small>{run.status} · {run.prompt_version}</small></span><button className="icon-button" title="检查 Prompt" aria-label="检查 Prompt" onClick={() => void inspectRun(run)}><Eye size={15} /></button><button className="icon-button" title="dry-run 重放" aria-label="dry-run 重放" onClick={() => void dryReplay(run)}><RotateCcw size={15} /></button></div>)}</div></section></div>}
    {showInput && <div className="modal-backdrop" role="presentation" onClick={() => !busy && setShowInput(false)}><section className="admin-panel input-panel" role="dialog" aria-modal="true" onClick={(event) => event.stopPropagation()}><div className="panel-heading"><div><p className="eyebrow">{activeEntry.label}</p><h2>准备输入</h2></div><button className="icon-button" title="关闭" aria-label="关闭" onClick={() => setShowInput(false)}><X size={18} /></button></div>{entry === "page_entry" ? <textarea className="input-textarea" value={inputText} onChange={(event) => setInputText(event.target.value)} placeholder="标题\n正文\n---\n下一页标题\n正文" rows={12} /> : <><label className="file-picker"><Upload size={17} />{inputFile?.name || "选择资料文件"}<input type="file" accept=".md,.markdown,.txt,.docx,.pdf,.pptx" onChange={(event) => setInputFile(event.target.files?.[0] || null)} /></label><textarea className="input-textarea" value={inputText} onChange={(event) => setInputText(event.target.value)} placeholder="或者粘贴资料文本" rows={8} /></>}<details className="advanced-input"><summary>高级设置</summary><div className="advanced-grid"><label>语言<input value={design.language} onChange={(event) => setDesign({ ...design, language: event.target.value })} placeholder="自动推断" /></label><label>受众<input value={design.audience} onChange={(event) => setDesign({ ...design, audience: event.target.value })} /></label><label>目的<input value={design.purpose} onChange={(event) => setDesign({ ...design, purpose: event.target.value })} /></label><fieldset><legend>页数</legend><div className="segmented"><button type="button" className={design.pageCountMode === "exact" ? "active" : ""} onClick={() => setDesign({ ...design, pageCountMode: "exact" })}>精确</button><button type="button" className={design.pageCountMode === "range" ? "active" : ""} onClick={() => setDesign({ ...design, pageCountMode: "range" })}>范围</button><button type="button" className={design.pageCountMode === "auto" ? "active" : ""} onClick={() => setDesign({ ...design, pageCountMode: "auto" })}>AI 建议</button></div>{design.pageCountMode === "exact" && <input type="number" min="1" max="100" value={design.pageCountExact} onChange={(event) => setDesign({ ...design, pageCountExact: event.target.value })} />}{design.pageCountMode === "range" && <div className="range-inputs"><input type="number" min="1" max="100" value={design.pageCountMin} onChange={(event) => setDesign({ ...design, pageCountMin: event.target.value })} /><input type="number" min="1" max="100" value={design.pageCountMax} onChange={(event) => setDesign({ ...design, pageCountMax: event.target.value })} /></div>}</fieldset><label className="check-label"><input type="checkbox" checked={design.logicDiagnosis} onChange={(event) => setDesign({ ...design, logicDiagnosis: event.target.checked })} />内容逻辑诊断</label><fieldset><legend>内容计划导出</legend><div className="check-row"><label><input type="checkbox" checked={design.outputMarkdown} onChange={(event) => setDesign({ ...design, outputMarkdown: event.target.checked })} />MD</label><label><input type="checkbox" checked={design.outputTxt} onChange={(event) => setDesign({ ...design, outputTxt: event.target.checked })} />TXT</label><label><input type="checkbox" checked={design.outputDocx} onChange={(event) => setDesign({ ...design, outputDocx: event.target.checked })} />DOCX</label></div></fieldset><label className="wide">补充指令<textarea value={design.userInstruction} onChange={(event) => setDesign({ ...design, userInstruction: event.target.value })} rows={3} /></label></div></details><div className="start-actions"><button className="primary-button" disabled={busy || (!design.outputMarkdown && !design.outputTxt && !design.outputDocx)} onClick={() => void submitEntry()}><ArrowRight size={17} />{busy ? "提交中…" : "创建内容计划"}</button></div></section></div>}
    {pendingOperation && <div className="modal-backdrop" role="presentation"><section className="admin-panel" role="dialog" aria-modal="true"><div className="panel-heading"><div><p className="eyebrow">二次确认</p><h2>内容或设计将失效</h2></div><button className="icon-button" title="取消" aria-label="取消" onClick={() => setPendingOperation(null)}><X size={18} /></button></div><div className="warning-box">{pendingOperation.structured_plan?.confirmationReasons?.join(" · ")}</div><div className="start-actions"><button className="primary-button" disabled={busy} onClick={() => void confirmEdit()}><Check size={16} />继续修改</button><button className="text-button" onClick={() => setPendingOperation(null)}>取消</button></div></section></div>}
    {runInspection && <div className="modal-backdrop" role="presentation" onClick={() => setRunInspection(null)}><section className="admin-panel inspection-panel" role="dialog" aria-modal="true" onClick={(event) => event.stopPropagation()}><div className="panel-heading"><div><p className="eyebrow">Prompt 检查</p><h2>{runInspection.agent_run?.role || runInspection.mode}</h2></div><button className="icon-button" title="关闭" aria-label="关闭" onClick={() => setRunInspection(null)}><X size={18} /></button></div><pre>{JSON.stringify(runInspection, null, 2)}</pre></section></div>}
    {preflight && <div className="modal-backdrop" role="presentation" onClick={() => !busy && setPreflight(null)}><section className="admin-panel disclosure-panel" role="dialog" aria-modal="true" onClick={(event) => event.stopPropagation()}><div className="panel-heading"><div><p className="eyebrow">重建前检查</p><h2>第 {preflight.page_id} 页</h2></div><button className="icon-button" title="关闭" aria-label="关闭" onClick={() => setPreflight(null)}><X size={18} /></button></div><div className="disclosure-grid"><span>预计等待<strong>{preflight.estimated_wait_seconds} 秒</strong></span><span>Agent 调用<strong>{preflight.estimated_agent_calls}</strong></span><span>图片调用<strong>{preflight.estimated_image_calls}</strong></span><span>供应商费用风险<strong>{preflight.supplier_fee_risk ? "有" : "无"}</strong></span></div><p className="muted">{preflight.visual_difference_risk}</p><p className="muted">{preflight.editable_boundary}</p>{preflight.unsupported_items.length > 0 && <div className="warning-box">有 {preflight.unsupported_items.length} 个来源对象需要登记为不可编辑区域。</div>}<button className="primary-button" disabled={busy} onClick={() => void acceptPreflight()}><Check size={16} />同意披露并提交重建</button></section></div>}
  </div>;
}

export default App;

createRoot(document.getElementById("root")!).render(<App />);
